style.css:
@-moz-document url-prefix("https://www.roblox.com") {
:root {
    --pastel-bg: #f8eaff;      
    --pastel-card: #fff5fb;    
    --pastel-focus: #cfe9ff;   
    --pastel-text: #5b5770;    
    --pastel-link: #7aa7ff;    
  }

  body {
    background: var(--pastel-bg) !important;
    color: var(--pastel-text) !important;
  }

  /* Cuadros, paneles y módulos */
  .container, .content, .section, .game-card, .card-item, .item-card {
    background: var(--pastel-card) !important;
    border-radius: 14px !important;
    box-shadow: 0 4px 14px rgba(220,190,255,0.25) !important;
  }

  /* Links */
  a {
    color: var(--pastel-link) !important;
  }

  /* Cuadros de texto (si aparecen) */
  input, textarea {
    background: var(--pastel-card) !important;
    border: 2px solid var(--pastel-focus) !important;
    border-radius: 10px !important;
    color: var(--pastel-text) !important;
  }
}
